ClientFiles = {
    init: async function (app, container, clientEntry) {
        app = app || session.app;
        container = container || $(".component[name=ClientFiles]");
        await api.add("DMS/" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content/Slideshow");
        await api.add("DMS/" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content/Flags");
        await api.add("DMS/" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content");
        var slideShowFolder = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq '" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content/Slideshow' ")).value;
        slideShowFolder = slideShowFolder[0];
        var flagsFolder = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq '" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content/Flags' ")).value;
        flagsFolder = flagsFolder[0];
        var contentFolder = (await api.get("DocumentManagement/Folder?$filter=AppId eq " + app.Id + " and Path eq '" + app.Config.CRM.ClientFolder + clientEntry.name + "/Content' ")).value;
        contentFolder = contentFolder[0];
        loadComponent($("[name=folderManagementSlideshow]", container), "FolderManagement", (comp) => {
            comp.init(app, $("[name=folderManagementSlideshow]", container), slideShowFolder, false, true, true);
        });
        loadComponent($("[name=folderManagementFlags]", container), "FolderManagement", (comp) => {
            comp.init(app, $("[name=folderManagementFlags]", container), flagsFolder, false, true, true);
        });
        loadComponent($("[name=folderManagementContent]", container), "FolderManagement", (comp) => {
            comp.init(app, $("[name=folderManagementContent]", container), contentFolder, false, true, true);
        });
        $(".partsList > ul > li", container).on("click", function (e) {
            $(".partsList > ul > li", container).removeClass("selected");
            $(".sectionContainer", container).css("display", "none");
            $(".sectionContainer[name=" + $(e.target).attr("data-container") + "]").css("display", "inline-block");
            $(e.target).addClass("selected");
        });
        $(".sectionContainer", container).hide();
        $(".sectionContainer[name=" + $(".partsList > ul > li.selected", container).attr("data-container") + "]").show();
    }
}
